if(new URLSearchParams(location.search).get('video')==='1')document.documentElement.classList.add('video-neutral');
const $=s=>document.querySelector(s);
const state={brief:'We’re launching a customer portal in four weeks. Design and engineering will work in parallel. We need customer feedback each week, a security review, and a clear launch decision.',view:'Board',risk:false,voice:false,memory:false,artifact:false,session:false,role:'manager'};
const routes=[['morning','☀  Morning brief'],['meeting-plan','✦  Your meeting, already organized'],['assistant','✦  In your assistant'],['brief','＋  Start a project'],['risk','◷  Delivery decisions'],['meeting','◉  In a Zoom meeting'],['room','▣  In the meeting room'],['voice','♫  Talk to your plan'],['learning','♡  What we remember'],['developer','☷  Your work view'],['create','↗  Make a starting point']];
$('#concept-nav').innerHTML=routes.map(([r,t])=>`<button data-route="${r}" onclick="go('${r}')">${t}</button>`).join('');
function go(r){location.hash=r}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function head(k,t,s,action=''){return `<div class="eyebrow">${k}</div><div class="page-head"><div><h1>${t}</h1><p class="sub">${s}</p></div>${action}</div>`}
const av=(s,c='')=>`<span class="avatar ${c}">${s}</span>`;
function task(t,who,date,tag=''){return `<div class="task-card"><p>${t}</p><div class="row spread"><span>${av(who)} &nbsp; ${date}</span>${tag?`<span class="tag ${['Review','At risk'].includes(tag)?'amber':'green'}">${tag}</span>`:''}</div></div>`}
const home=()=>head('Sunday, October 18','Good morning, Aditya','Two things need you today. The rest is moving along.',`<select class="role-switch" aria-label="Your role" onchange="state.role=this.value;go('developer')"><option value="manager">Project manager view</option><option value="developer">Developer view</option></select>`)+`<div class="notice"><span>◷</span><div><strong>Let’s keep the portal launch on track</strong><p>Security review and API integration overlap. Two ways to protect the date are ready.</p></div><button onclick="go('risk')">Review options →</button></div><div class="grid two"><section class="card"><div class="row spread"><h2>Needs your judgment <span class="tag gray">2</span></h2><span class="tiny muted">Prioritized for you</span></div><div class="item"><span class="agent-icon">✦</span><div><h3>Starter flow is ready for review</h3><p>A portal flow drafted from your brief and approved design references.</p><span class="tag">Based on 3 sources</span></div><button onclick="go('create')">Review</button></div><div class="item"><span class="agent-icon">↗</span><div><h3>Choose how to handle Sam’s capacity</h3><p>8 hours of security work overlap with the integration milestone.</p><span class="tag amber">Delivery risk</span></div><button onclick="go('risk')">Decide</button></div></section><section class="card"><h2>Moving without you</h2><p class="tiny">Within the scope you approved</p><div class="line"><span><span class="bullet"></span>Draft weekly launch update</span><span class="tag green">Drafting</span></div><div class="line"><span><span class="bullet"></span>Check linked pull requests</span><span class="tag gray">Watching</span></div><div class="line"><span><span class="bullet"></span>Prepare feedback summary</span><span class="tag gray">Queued</span></div><p class="sourceline">Actions and source material stay attached to the project.</p></section></div><div class="grid three spaced"><div class="card"><div class="tiny muted">CUSTOMER PORTAL</div><div class="metric">Oct 30</div><p class="tiny">Target launch · 12 days away</p><div class="progress"><i style="width:62%"></i></div><button class="inline-link" onclick="go('board')">Open project →</button></div><div class="card"><div class="tiny muted">TODAY’S FOCUS</div><div class="metric">2 decisions</div><p class="tiny">Review the flow. Resolve the capacity conflict.</p><button class="inline-link" onclick="go('assistant')">Talk it through →</button></div><div class="card tint"><h3>What are you trying to achieve?</h3><p class="tiny">Bring a brief. We’ll work out a starting plan together.</p><button onclick="go('brief')">Start something new +</button></div></div>`;
const assistant=()=>head('Principles 1 + 2 / Wherever you work','Your assistant. Your work.','Your project, right beside the conversation.')+`<div class="assistant-layout"><section class="chat"><div class="row"><span class="agent-icon">✦</span><h3>Your assistant</h3></div><div class="bubble">What needs my attention on the customer portal this week?</div><div class="reply">The launch plan is mostly on track. Sam’s security review overlaps with API integration.<br><br>I’ve brought the important work into this view. You can inspect the risk or open the full project.</div><div class="divider"></div><span class="tag green">Asana connected · MCP</span><p class="tiny">Work stays connected to the same project.</p><div class="composer">Ask a follow-up… <span style="float:right">↑</span></div></section><section class="embedded"><div class="row spread"><span class="mini-brand"><span>● ● ●</span> asana</span><span class="tag gray">Embedded project view · concept</span></div><div class="divider"></div><div class="row spread"><h2>Customer portal</h2><span class="tag amber">Needs attention</span></div><p class="tiny">Launch Oct 30 · Product & engineering</p><div class="grid three"><div><div class="metric">18 / 29</div><span class="tiny muted">tasks accepted</span></div><div><div class="metric">1</div><span class="tiny muted">delivery risk</span></div><div><div class="metric">2</div><span class="tiny muted">decisions needed</span></div></div><div class="divider"></div><div class="task-row"><span class="check"></span><span>Complete API integration</span>${av('SL')}<span>Oct 22</span></div><div class="task-row"><span class="check"></span><span>Security review</span>${av('SL')}<span class="tag amber">At risk</span></div><div class="task-row"><span class="check"></span><span>Review portal starter flow</span>${av('AV','coral')}<span>Today</span></div><div class="foot-actions"><button onclick="go('board')">Open project</button><button class="primary" onclick="go('risk')">Review delivery risk →</button></div></section></div>`;
const brief=()=>head('Principle 4 / Bring project expertise','Tell us what you’re trying to achieve','Start with the project. We’ll recommend a way to manage it.')+`<section class="form-area"><div class="step">1 &nbsp; Your brief &nbsp; ───── &nbsp; 2 &nbsp; A recommended approach &nbsp; ───── &nbsp; 3 &nbsp; Your workspace</div><div class="card tint"><h2>A little context goes a long way</h2><p class="sub">What are you building, who is involved, and when does it need to happen?</p><label for="brief-input" class="tiny muted">PROJECT BRIEF</label><textarea id="brief-input" class="briefbox">${state.brief}</textarea><input id="brief-file" type="file" accept=".txt" hidden onchange="loadBrief(this)"><button class="upload" onclick="document.getElementById('brief-file').click()">↑ &nbsp; Or upload a text brief (.txt)</button><div class="row spread"><span class="tiny muted">You can change the recommendation.</span><button class="primary" onclick="state.brief=$('#brief-input').value;go('plan')">Recommend an approach →</button></div></div><p class="tiny muted">This demo uses a prepared recommendation for the customer portal example.</p></section>`;
async function loadBrief(el){if(el.files[0]){$('#brief-input').value=await el.files[0].text();toast('Brief loaded locally. No upload or external service used.')}}
const plan=()=>head('Principle 4 / An opinion, with a reason','A Kanban board, with a launch checkpoint','A starting plan for your portal. Make it yours.')+`<div class="recommend"><section class="card"><span class="tag green">Recommended for this brief</span><div class="empty-space"></div><div class="big-icon">▥</div><h2>Keep parallel work moving</h2><p class="sub">Design and engineering will overlap. A board keeps work moving; a launch checkpoint keeps the date in view.</p><ul class="reasons"><li>Work moves continuously across design and development.</li><li>Weekly feedback can add or change tasks.</li><li>A “Ready for review” stage separates output from acceptance.</li><li>A security checkpoint keeps the launch decision explicit.</li></ul><div class="row"><span class="tiny muted">Prefer another view?</span><button onclick="state.view=state.view==='Board'?'List':'Board';render()">Use ${state.view==='Board'?'list':'board'} instead</button></div></section><section class="card tint"><h3>Your starting workspace</h3><div class="line"><span>Project view</span><strong>${state.view==='Board'?'Kanban board':'Task list'}</strong></div><div class="line"><span>Workflow</span><span>To do → In progress → Review</span></div><div class="line"><span>Weekly rhythm</span><span>Customer feedback · Fridays</span></div><div class="line"><span>Key checkpoint</span><span>Security sign-off · Oct 28</span></div><div class="line"><span>Launch decision</span><span>Oct 30 · Aditya</span></div><div class="divider"></div><h3>Suggested first steps</h3><p class="tiny">Confirm scope, draft the portal flow, connect development evidence, and assign the security review.</p><div class="quote-note">“A little structure to get you started. Room to change it as you go.”</div><div class="foot-actions"><button class="primary" onclick="go('board');toast('Sample workspace prepared from your brief')">Use this starting plan →</button></div></section></div>`;
const board=()=>head('Customer portal / Project','A shared plan, with the work attached','People and capabilities work against the same brief, dates, and acceptance criteria.',`<button onclick="go('voice')">◉ &nbsp; Talk to this plan</button>`)+`<div class="row spread"><div class="tabs"><button class="selected">Work</button><button onclick="go('risk')">Risks & decisions</button><button onclick="go('create')">Outputs</button></div><div class="view-toggle"><button class="${state.view==='Board'?'selected':''}" onclick="state.view='Board';render()">Board</button><button class="${state.view==='List'?'selected':''}" onclick="state.view='List';render()">List</button></div></div>${state.view==='Board'?`<div class="board"><section class="column"><h3>To do <span class="muted">${state.meetingPlanApplied?4:3}</span></h3>${task('Run customer feedback session','AK','Oct 23')}${state.meetingPlanApplied?task('Accessibility check','AL','Oct 23','Assigned'):''}${task('Confirm launch checklist','AV','Oct 28')}${task('Draft customer announcement','✦','Oct 26')}</section><section class="column"><h3>In progress <span class="muted">2</span></h3>${task('Complete API integration','SL','Oct 22','At risk')}${task('Prepare starter portal flow','✦','Today','Draft')}</section><section class="column"><h3>Ready for review <span class="muted">2</span></h3>${task('Review authentication requirements','AV','Today','Review')}${task('Approve portal copy','AK','Oct 21','Review')}<button style="width:100%" onclick="go('create')">Review generated starter →</button></section></div>`:`<table class="list-table"><thead><tr><th>Task</th><th>Owner</th><th>Due</th><th>Status</th></tr></thead><tbody><tr><td>Complete API integration</td><td>Sam</td><td>Oct 22</td><td>In progress</td></tr><tr><td>Prepare starter portal flow</td><td>Assistant · Aditya accountable</td><td>Today</td><td>Draft</td></tr><tr><td>Review authentication requirements</td><td>Aditya</td><td>Today</td><td>Ready for review</td></tr>${state.meetingPlanApplied?'<tr><td>Accessibility check</td><td>Alex</td><td>Oct 23</td><td>Assigned</td></tr>':''}<tr><td>Security review</td><td>${state.risk?'Priya':'Sam'}</td><td>Oct 23</td><td>At risk</td></tr></tbody></table>`}<div class="foot-actions"><button onclick="go('learning')">Teach a project preference</button><button class="primary" onclick="go('risk')">Review capacity risk →</button></div>`;
const risk=()=>head('Principle 4 / Proactive project expertise',state.risk?'A plan you’ve adjusted':'A risk worth your attention',state.risk?'Priya takes the review. Sam keeps the integration.':'One overlap. Two ways to protect your launch.')+`<div class="risk-layout"><section class="card"><div class="row spread"><h2>${state.risk?'Security review reassigned':'Sam has two overlapping commitments'}</h2><span class="tag ${state.risk?'green':'amber'}">${state.risk?'Resolved in demo':'Capacity conflict'}</span></div><p class="sub">API integration and security review share the same owner during October 21–23.</p><div class="row">${av('SL')}<strong>Sam Lee</strong><span class="tiny muted">· 32 hours available this week</span></div><div class="capacity"><i style="width:${state.risk?'75':'100'}%"></i></div><div class="row spread tiny"><span>${state.risk?'30':'38'} hours planned</span><span class="muted">${state.risk?'2 hours remaining':'6 hours over capacity'}</span></div><div class="evidence"><h3>Why this may affect the launch</h3><p>The security review is a launch dependency. Integration is still in review, and its linked pull request has failing checks.</p><div class="row"><span class="tag gray">Asana assignments</span><span class="tag gray">Linked PR #184</span></div><p class="tiny muted">Sample evidence · last checked 9:10 AM</p></div><p class="tiny">${state.risk?'Priya owns the 8-hour security review. Sam keeps API integration. You remain accountable for the launch decision.':'Capacity is an estimate. This does not prove the milestone will slip; it is a reason to check.'}</p></section><section class="card tint"><h2>${state.risk?'Decision recorded':'Two ways forward'}</h2>${state.risk?`<div class="memory-card remembered"><strong>Move the review, protect the date</strong><p>Security review → Priya<br>Launch target → Oct 30<br>Reason → Resolve overlapping commitments</p></div><button class="primary" onclick="go('board')">Back to the shared plan →</button><p class="tiny muted">Prototype state only. Nobody has been notified.</p>`:`<h3>1. Reassign the security review</h3><p class="tiny">Priya has the required skill and 10 hours available. Keeps the launch target unchanged.</p><button class="primary" onclick="state.risk=true;render();toast('Sample plan updated. Decision recorded.')">Review and apply reassignment</button><div class="divider"></div><h3>2. Keep Sam, move the checkpoint</h3><p class="tiny">Push the review to Oct 26. Leave less room for follow-up fixes.</p><button onclick="toast('Alternative: Oct 26 review, two days for follow-up. No change applied.')">Inspect alternative</button><div class="divider"></div><button class="inline-link" onclick="go('learning')">This overlap is intentional →</button>`}</section></div>`;
const meeting=()=>head('Principle 5 / Voice in a group meeting','The plan is in the meeting with you','Keep talking. Review the change together.',`<span class="meeting-pill">● &nbsp; Sample Zoom meeting</span>`)+`<div class="meeting-layout"><section><div class="call-stage"><div class="participants"><div class="person-tile"><span>AV</span><small>Aditya · Project lead</small></div><div class="person-tile"><span>SL</span><small>Sam · Engineering</small></div><div class="person-tile"><span>PN</span><small>Priya · Security</small></div><div class="person-tile" style="background:#443c50"><span>✦</span><small>Asana · Shared project context</small></div></div><div class="call-controls">♩ ▣ ⤴ ☰ <span style="color:#e59494">▰</span></div></div><div class="transcript"><span class="tiny muted">ADITYA · SAMPLE TRANSCRIPT</span><br>“Move the security review to Priya. Keep the launch date, and flag anything that puts it at risk.”</div></section><section class="card meeting-notes"><span class="tag">Customer portal · Linked project</span><div class="empty-space"></div><h2>Heard a decision. Prepared a change.</h2><div class="item"><span>✓</span><div><h3>Security review</h3><p>Owner: Sam → Priya<br>Due: Oct 23 · Unchanged</p></div></div><div class="item"><span>✓</span><div><h3>Launch checkpoint</h3><p>Oct 30 · Keep watching dependencies</p></div></div><p class="tiny">Aditya approves the change. The decision links back to this meeting.</p><button class="primary" onclick="state.risk=true;toast('Meeting decision applied to the sample plan');this.textContent='✓ Change applied'">Approve sample change</button><p class="sourceline">Concept only · no meeting joined, recorded, or transcribed.</p><div class="divider"></div><button class="inline-link" onclick="go('room')">See the physical meeting room →</button></section></div>`;
const room=()=>head('Principle 5 / Voice in the physical room','One shared board. A conversation around it.','Ask a question. Bring the answer into the room.')+`<div class="room-screen"><div class="row spread"><span class="tiny muted">CUSTOMER PORTAL · ROOM DISPLAY</span><span class="tag">Voice example</span></div><div class="empty-space"></div><h2>“Are we still on for October 30?”</h2><p>One dependency needs attention before we can say yes with confidence.</p><div class="room-timeline"><div><span class="tag green">In progress</span><h3 class="spaced">API integration</h3><span class="tiny muted">Oct 22 · Sam</span></div><div><span class="tag amber">Decision needed</span><h3 class="spaced">Security review</h3><span class="tiny muted">Oct 23 · Owner overlap</span></div><div><span class="tag gray">Target</span><h3 class="spaced">Launch decision</h3><span class="tiny muted">Oct 30 · Aditya</span></div></div><div class="row spread"><span class="tiny muted">Based on the plan and linked development checks · sample data</span><button class="primary" onclick="go('risk')">Show the options →</button></div></div><div class="row spread"><p class="sub">People keep talking. The shared display keeps the work and the decision visible.</p><button onclick="go('voice')">See solo voice editing →</button></div>`;
const voice=()=>head('Principle 5 / Voice while working alone','Talk through the change. See the plan respond.','Say what you want to change. We’ll show you first.')+`<div class="voice-layout"><section class="card voice-panel"><div class="row spread"><h3>Talk to your plan</h3><span class="tag gray">Simulated voice</span></div><div class="wave">${[12,25,42,24,53,36,62,28,48,19,34,12].map(n=>`<i style="--h:${n}px"></i>`).join('')}</div><blockquote>“Add an accessibility check before the security review. Ask Alex to own it.”</blockquote><p class="tiny">${state.voice?'Here’s the change. Does it look right?':'Try the voice example. Your microphone stays off.'}</p><div class="foot-actions" style="margin-top:auto">${state.voice?`<button onclick="state.voice=false;render()">Undo preview</button><button class="primary" onclick="toast('Sample accessibility task added. No external changes.');this.textContent='✓ Applied'">Apply change</button>`:`<button class="primary" onclick="state.voice=true;render()">▶ Play voice example</button>`}</div></section><section class="card gantt-plan"><div class="row spread"><div><span class="tiny muted">CUSTOMER PORTAL</span><h2>Launch plan</h2></div><span class="tag ${state.voice?'green':'gray'}">${state.voice?'Proposed change':'Current plan'}</span></div><div class="gantt-table"><div class="gantt-label tiny muted">TASK / OWNER</div><div class="gantt-days"><span>Oct 20</span><span>22</span><span>24</span><span>26</span><span>28</span><span>30</span></div>${[['API integration','Sam',0,27,'lilac'],...(state.voice?[['Accessibility check','Alex',27,13,'sage']]:[]),['Security review',state.risk?'Priya':'Sam',40,18,'peach'],['Launch decision','Aditya',88,12,'lilac']].map(([name,owner,left,width,color])=>`<div class="gantt-label"><strong>${name}</strong><small>${owner}${name==='Accessibility check'?' · New task':''}</small></div><div class="gantt-track"><div class="gantt-bar ${color}" style="left:${left}%;width:${width}%" title="${name}"></div></div>`).join('')}</div><p class="sourceline">${state.voice?'New: accessibility check assigned to Alex, before security review. Launch date stays October 30.':'A shared schedule with owners and dates. Speak to prepare a change.'}</p></section></div>`;
const learning=()=>head('Principle 6 / Learn the reason behind a correction','An exception is useful context','Tell us why. We’ll use it next time.')+`<div class="grid equal"><section class="card"><span class="tag amber">Capacity warning · Sam Lee</span><div class="bubble">This overlap is intentional. Sam is pairing with Priya on the review, so don’t count both tasks as full-time work this week.</div><h2>What should we remember?</h2><div class="memory-card ${state.memory?'remembered':''}"><strong>Pairing changes the capacity estimate</strong><p>For the customer portal this week, treat Sam’s security review as shared pairing time.</p><div class="line"><span>Scope</span><span>This project only</span></div><div class="line"><span>Expires</span><span>Oct 23</span></div><div class="line"><span>Confirmed by</span><span>Aditya</span></div></div><button class="primary" onclick="state.memory=true;render();toast('Project exception saved in this demo')">${state.memory?'✓ Exception remembered':'Remember this exception'}</button></section><section class="card tint"><h2>A little more understanding</h2><p class="sub">We’ll account for pairing. We’ll still flag a failing security check.</p><div class="item"><span>✓</span><div><h3>Explain what changed</h3><p>Use the adjustment when estimating this week’s work.</p></div></div><div class="item"><span>◷</span><div><h3>Ask again when the exception expires</h3><p>Don’t turn one project’s exception into a permanent rule.</p></div></div><div class="item"><span>↗</span><div><h3>Check whether it helped</h3><p>Did the project stay on track? Did the warning return?</p></div></div><button onclick="state.memory=false;render();toast('Exception removed from the sample memory')">Reset exception</button><button class="inline-link" style="margin-left:14px" onclick="go('developer')">See a different work view →</button></section></div>`;
const developer=()=>head('Principle 3 / Dynamic interfaces',state.role==='developer'?'Your next two days, Alex':'The delivery view, Aditya',state.role==='developer'?'The work you can act on, with the evidence and the deadline in view.':'Schedules, dependencies, and decisions across the project.',`<select class="role-switch" aria-label="Work view" onchange="state.role=this.value;render()"><option value="manager" ${state.role==='manager'?'selected':''}>Project manager</option><option value="developer" ${state.role==='developer'?'selected':''}>Developer</option></select>`)+`${state.role==='manager'?`<div class="notice"><div><strong>Launch readiness depends on two pieces of evidence</strong><p>API checks and security sign-off need review before the Oct 30 decision.</p></div><button onclick="go('risk')">Inspect risk →</button></div><div class="grid equal"><section class="card"><h2>Delivery milestones</h2><div class="line"><span>API integration · Oct 22</span><span class="tag amber">Checks failing</span></div><div class="line"><span>Security review · Oct 23</span><span class="tag gray">Pending</span></div><div class="line"><span>Launch decision · Oct 30</span><span class="tag">Aditya</span></div><p class="sourceline">Connected evidence is an input, not a substitute for acceptance.</p></section><section class="card tint"><h2>Questions to resolve</h2><p>Is the review owner confirmed? Are failing checks blocking acceptance? Is the scope still realistic?</p><button onclick="state.role='developer';render()">See what the developer sees →</button></section></div>`:`<div class="banner"><strong>API integration is due in 2 days. The linked checks are still failing.</strong><p>The pull request is open, but the task is not ready to call complete. Review the failure or let Aditya know what changed.</p></div><div class="grid two spaced"><section class="card"><div class="row spread"><h2>Continue API integration</h2><span class="tag amber">Needs attention</span></div><p class="tiny">Customer portal / Engineering / Due Oct 22</p><div class="code">PR #184 · feat/customer-portal-api<br>✓ Type check<br>✓ Unit tests<br>× Integration / authentication callback<br>Review requested · 1 unresolved comment</div><div class="divider"></div><h3>What will count as done?</h3><p class="tiny">Authentication works end to end, checks pass, and the reviewer accepts the change.</p><button class="primary" onclick="go('create')">Prepare a coding handoff →</button><button style="margin-left:8px" onclick="toast('Draft prepared: API integration may slip; authentication callback needs a fix. Nothing sent.')">Draft update for Aditya</button></section><section class="card tint"><h2>Why this is first</h2><p class="tiny">Security review depends on this integration. Your design cleanup task can wait until the callback is fixed.</p><div class="evidence"><strong class="tiny">Signals used</strong><p>Linked pull request, current checks, reviewer comments, and the project dependency.</p></div><button class="inline-link" onclick="go('board')">See the whole plan →</button></section></div>`}`;
const create=()=>head('Beyond coordination / Get the work done','One request. The right capabilities behind it.','A useful first draft. Your choice of where to take it next.')+`<div class="grid two"><section class="card"><div class="row spread"><h2>Customer portal starter</h2><span class="tag ${state.artifact?'green':'gray'}">${state.artifact?'Draft ready':'Ready to generate'}</span></div><p class="sub">“Use our approved references and portal brief to give us a starting flow and implementation plan.”</p>${state.artifact?`<div class="room-timeline"><div><h3>Sign in</h3><p class="tiny">Email + verification</p><div style="height:6px;background:#ede9e3;margin:18px 0"></div><button style="font-size:10px" onclick="toast('Sample sign-in screen selected')">Continue</button></div><div><h3>Your workspace</h3><p class="tiny">Requests · Documents</p><div class="tag green">3 updates</div></div><div><h3>Request detail</h3><p class="tiny">Status · Owner · History</p><span class="tag">In progress</span></div></div><p class="sourceline">Illustrative artifact · generated locally from prepared sample content</p>`:`<div class="quote-note"><strong>Starting context</strong><p class="tiny">Portal brief · Approved design references · Authentication requirements</p><strong>Expected output</strong><p class="tiny">A reviewable starter flow, component outline, and scoped coding task.</p></div><div class="foot-actions"><button class="primary" onclick="state.artifact=true;render()">Generate sample starter →</button></div>`}<div class="divider"></div><div class="row"><span class="agent-icon">✦</span><p class="tiny">You speak to one assistant. Design, planning, and coding are capabilities it can bring in. Aditya remains accountable for acceptance.</p></div></section><section class="card tint"><h2>Take it into your tools</h2><p class="tiny">Keep the context and acceptance criteria attached when work moves to a specialist tool.</p><button style="width:100%;text-align:left" onclick="toast('Concept handoff: starter flow and references prepared for Figma. Nothing uploaded.')">↗ &nbsp; Prepare Figma handoff</button><div class="empty-space"></div><label class="tiny muted" for="coding-tool">CODING ENVIRONMENT</label><select id="coding-tool" class="role-switch" style="width:100%;margin:8px 0 14px"><option>Codex</option><option>Claude Code</option></select><div class="code">Task: Implement authentication flow<br>Scope: Feature branch only<br>Done: Checks pass + human review<br>Context: Brief, flow, requirements<br>Access: Approved repository only</div><div class="foot-actions"><button class="primary" onclick="state.session=true;render();toast('Sample coding handoff prepared. No session was started.')">${state.session?'✓ Handoff prepared':'Prepare coding session →'}</button></div>${state.session?'<div class="finish">Ready for your review. In a connected product, this is where you would approve access and start the session.</div>':''}<p class="sourceline">Concept only · no coding tool or external service is connected.</p></section></div>`;
const morning=()=>{const engineering=state.briefFocus==='building',stage=state.morningStage??0;return `<div class="pm-dashboard"><div class="brief-masthead"><span>MONDAY, OCTOBER 19 · 08:30</span><span>YOUR PERSONALIZED BRIEF</span></div><div class="page-head"><div><div class="pm-persona">${av('AV','coral')} FOR ADITYA · ${engineering?'ENGINEERING FOCUS':'PROJECT MANAGER'}</div><h1>${engineering?'Fix the blocker. Keep work moving.':'Hi Aditya, here’s where your project stands.'}</h1><p class="sub">Customer portal · Launch target October 30</p></div><select class="role-switch" aria-label="Brief focus" onchange="state.briefFocus=this.value;render()"><option value="delivery" ${!engineering?'selected':''}>Project manager</option><option value="building" ${engineering?'selected':''}>Engineering</option></select></div><div class="pm-layout"><section class="card pm-status morning-timeline"><div class="row spread"><div><div class="brief-label">CUSTOMER PORTAL · OCT 19–30</div><h2>Here’s the progress of your key items.</h2></div><button class="inline-link" onclick="go('board')">Full project ↗</button></div><div class="brief-sequence" aria-label="Morning briefing steps">${[['The plan','◷'],['On track','✓'],['Needs attention','!'],['Proposed actions','↗']].map(([label,icon],i)=>`<button class="${stage===i?'selected':''}" aria-pressed="${stage===i}" onclick="state.morningStage=${i};render()"><span>${icon}</span>${label}</button>`).join('')}</div><div class="brief-gantt"><div class="brief-gantt-head"><span>KEY ITEM / OWNER</span><div><span>Oct 19</span><span>22</span><span>25</span><span>28</span><span>30</span></div></div>${[['Portal design','Maya',0,25,100,'good','Accepted · ready for engineering'],['Customer feedback','Anika',8,33,65,'good','Participants confirmed · Oct 23'],['API integration','Sam',0,33,55,'blocked','Failing authentication check · PR #184'],['Security review',state.meetingPlanApplied?'Priya':'Sam',34,25,0,'watch',state.meetingPlanApplied?'Waiting for integration checks':'6 hours over capacity · depends on API'],['Launch decision','Aditya',90,10,0,'target','October 30 · target']].map(([name,owner,left,width,progress,kind,detail])=>{const active=kind==='good'?stage>=1:stage>=2;return `<div class="brief-gantt-row ${active?'revealed '+kind:''}"><div class="brief-gantt-name"><strong><span class="brief-check">${active?(kind==='good'?'✓':kind==='target'?'◇':'!'):'·'}</span>${name}</strong><small>${owner} ${active?'· '+(kind==='good'?'On track':kind==='blocked'?'Off track':kind==='watch'?'At risk':'Target'):''}</small></div><div class="brief-gantt-track"><div class="brief-gantt-bar" style="left:${left}%;width:${width}%"><i style="width:${progress}%"></i><span>${progress?progress+'%':''}</span></div></div>${active?`<p class="brief-row-reason">${detail}</p>`:''}</div>`}).join('')}</div><p class="sourceline">${stage===0?'Your plan first. Walk through what’s moving, what needs you, and what to do next.':stage===1?'✓ Design and customer feedback are on track. You can leave these moving.':stage===2?'Two connected risks need attention. The launch is a target, not a promise.':'Two proposed actions, linked to the work they protect. You choose what happens next.'}</p><div class="row spread brief-next-step"><span class="tiny muted">${stage+1} of 4 · Your morning briefing</span>${stage<3?`<button class="primary" onclick="state.morningStage=${stage+1};render()">${['Show what’s on track','Show what needs attention','Show proposed actions'][stage]} →</button>`:'<button onclick="state.morningStage=0;render()">↺ Replay briefing</button>'}</div></section>${stage<3?`<aside class="brief-narrator"><span class="brief-narrator-icon">${stage===0?'☀':stage===1?'✓':'!'}</span><div class="brief-label">${stage===0?'GOOD MORNING':stage===1?'MOVING WELL':'WHY THESE NEED YOU'}</div><h2>${stage===0?'A clear start to your day.':stage===1?'Two things you don’t need to chase.':'The review depends on the fix.'}</h2><p>${stage===0?'The portal launch is October 30. Let’s look at progress before we get into decisions.':stage===1?'Maya’s design is accepted. Anika’s feedback session is confirmed. Both are moving within the plan.':'Integration is 55% complete, but its authentication check is failing. Security review cannot start until it passes.'}</p>${stage===2?`<div class="brief-risk-note"><strong>Capacity adds a second risk.</strong><p>${state.meetingPlanApplied?'Priya now owns the review. The integration dependency remains.':'Sam is 6 hours over capacity. Priya has the skills and 10 hours available.'}</p></div><button onclick="state.morningStage=3;render()">See two proposed actions →</button>`:'<span class="tag green">'+(stage===0?'Prepared for your project manager view':'✓ Design · ✓ Customer feedback')+'</span>'}<div class="brief-label brief-source-note">SAMPLE PLAN · CHECKS · CAPACITY</div></aside>`:''}<aside class="pm-recommendations" ${stage<3?'hidden':''}><div class="brief-label">${state.meetingPlanApplied?'YOUR NEXT STEP · AND WHAT MOVED':'TWO RECOMMENDATIONS FOR YOU'}</div><article class="pm-recommendation"><div class="pm-rec-number">01 <span>UNBLOCK THE WORK</span></div><h2>${engineering?'Fix the authentication callback first.':'Get Sam’s fix plan today.'}</h2><p>Resolve the failing authentication check before the October 22 integration deadline. Keep Sam focused on this blocker.</p><div class="pm-impact">Protects the start of security review.</div><button class="primary" onclick="${engineering?"state.role='developer';go('developer')":"openBriefDraft('sam')"}">${engineering?'Open the blocked task →':'Review follow-up to Sam →'}</button></article><article class="pm-recommendation"><div class="pm-rec-number">02 <span>PROTECT THE NEXT MILESTONE</span></div><h2>${state.meetingPlanApplied?'You kept the review moving.':'Move the security review to Priya.'}</h2><p>She has the skills and 10 hours available. Sam stays on integration; the October 30 launch target stays in view.</p><div class="pm-impact">Removes the 6-hour capacity conflict.</div><button onclick="go(state.meetingPlanApplied?'meeting-plan':'risk')">${state.meetingPlanApplied?'See the reviewed plan →':'Review the reassignment →'}</button></article><div class="pm-board-note"><span>Keep stakeholders aligned.</span><button class="inline-link" onclick="openBriefDraft('board')">Draft a launch-board update ↗</button></div></aside></div><button class="prepared-surprise" onclick="go('meeting-plan')"><span class="prepared-mark">✦</span><span><small>READY BEFORE YOU ASKED</small><strong>${state.meetingPlanApplied?'Your meeting is now in the plan.':'Your meeting is already a plan.'}</strong><span>One new task. The right review owner. Your launch date kept.</span></span><span class="prepared-open">See what changed ↗</span></button><div class="brief-provenance">ILLUSTRATIVE DATA <span>Project plan</span><span>PR #184 checks</span><span>Team capacity</span><span>Meeting decisions</span></div></div><dialog id="brief-dialog"><button class="dialog-close" onclick="document.getElementById('brief-dialog').close()" aria-label="Close draft">×</button><span class="tag">Draft for your review</span><h2 id="draft-title"></h2><p id="draft-copy"></p><div class="divider"></div><p class="tiny muted">Sample only. No message has been sent.</p><button class="primary" onclick="document.getElementById('brief-dialog').close();toast('Draft kept for review. Nothing sent.')">Keep draft</button></dialog>`;};
function morningPrimary(){if(state.briefFocus==='building'){state.role='developer';go('developer')}else openBriefDraft('priya')}
function openBriefDraft(who){const drafts={sam:['To Sam · Unblock API integration','Hi Sam — the authentication check in PR #184 is still failing, and security review depends on it. Can you share your fix plan today and confirm whether October 22 is still achievable? We can move the security review to Priya so you can focus on the callback.'],priya:['To Priya · Confirm the review','Hi Priya — can you take the customer portal security review on October 23? You have 10 hours available; moving it from Sam would let him focus on API integration.'],board:['To the launch board · Morning update','Customer portal: portal design and the customer feedback session are on track. API integration is off track because the authentication check in PR #184 is failing. Security review is at risk due to Sam’s capacity. Recommended actions: get Sam’s fix plan today and move the security review to Priya. October 30 remains the launch target, subject to passing checks and review.']};const d=drafts[who]||drafts.board;document.getElementById('draft-title').textContent=d[0];document.getElementById('draft-copy').textContent=d[1];document.getElementById('brief-dialog').showModal()}

const meetingPlan=()=>{const reveal=state.meetingPlanReveal||state.meetingPlanApplied;return `<div class="meeting-magic"><div class="eyebrow">A LITTLE LESS WORK ABOUT WORK</div><div class="page-head"><div><h1>You talked. The plan caught up.</h1><p class="sub">Friday’s check-in, turned into two prepared updates. Ready for your review.</p></div><button onclick="go('morning')">← Your morning brief</button></div><div class="magic-summary"><span>✦</span><div><strong>${state.meetingPlanApplied?'That’s one less thing to organize.':'I turned the meeting into a plan for you.'}</strong><p>${state.meetingPlanApplied?'New task saved. Review reassigned. The meeting stays attached to both.':'I found the decisions, checked the owners, and kept the launch date in view.'}</p></div><span class="tag ${state.meetingPlanApplied?'green':'gray'}">${state.meetingPlanApplied?'Reviewed · Sample plan':'Prepared · Not applied'}</span></div><div class="magic-workspace"><aside class="meeting-source"><div class="brief-label">WHAT YOU SAID</div><div class="source-speaker">${av('AV','coral')} Aditya · Portal check-in</div><p class="decision-invite">Tap a decision. See where it landed.</p><blockquote><button class="spoken-decision ${state.meetingPlanFocus==='review'?'spoken-selected':''}" onclick="revealMeetingDecision('review')">“Move security review to Priya.</button><button class="spoken-decision ${state.meetingPlanFocus==='accessibility'?'spoken-selected':''}" onclick="revealMeetingDecision('accessibility')">Add an accessibility check for Alex before the review.</button><button class="spoken-decision ${state.meetingPlanFocus==='launch'?'spoken-selected':''}" onclick="revealMeetingDecision('launch')">Keep the October 30 launch.”</button></blockquote><div class="source-context"><span>◉</span> Friday, Oct 16 · 10:42 AM<br><small>Illustrative meeting transcript</small></div><div class="source-check"><strong>One thing I haven’t assumed.</strong><p>PR #184 still has a failing authentication check. The launch date remains a target until that passes.</p></div></aside><section class="card magic-plan"><div class="row spread"><div><div class="brief-label">CUSTOMER PORTAL</div><h2>${reveal?'Here’s what I prepared.':'Here’s where we left the plan.'}</h2></div><span class="tag ${reveal?'green':'gray'}">${reveal?'After the meeting':'Before the meeting'}</span></div><div class="magic-gantt"><div class="gantt-label tiny muted">TASK / OWNER</div><div class="gantt-days"><span>Oct 20</span><span>22</span><span>24</span><span>26</span><span>28</span><span>30</span></div><div class="gantt-label"><strong>API integration</strong><small>Sam · Check still failing</small></div><div class="gantt-track"><div class="gantt-bar lilac" style="left:0;width:27%"></div></div>${reveal?`<div class="gantt-label magic-arrive ${state.meetingPlanFocus==='accessibility'?'decision-target':''}"><strong>Accessibility check</strong><small>Alex <span class="new-note">New assignment</span></small></div><div class="gantt-track magic-arrive"><div class="gantt-bar sage" style="left:27%;width:13%"></div></div>`:''}<div class="gantt-label ${reveal&&state.meetingPlanFocus==='review'?'decision-target':''}"><strong>Security review</strong><small>${reveal?'<s>Sam</s> <strong class="changed-owner">→ Priya</strong>':'Sam'}</small></div><div class="gantt-track"><div class="gantt-bar ${reveal?'sage':'peach'}" style="left:40%;width:18%"></div></div><div class="gantt-label ${reveal&&state.meetingPlanFocus==='launch'?'decision-target':''}"><strong>Launch decision</strong><small>Aditya · Oct 30</small></div><div class="gantt-track"><div class="gantt-bar lilac" style="left:88%;width:12%"></div></div></div>${reveal?`<div class="magic-receipt magic-arrive"><div><strong>1 task added</strong><span>Accessibility check · Alex</span></div><div><strong>1 owner changed</strong><span>Security review · Priya</span></div><div><strong>Oct 30 kept</strong><span>Launch target unchanged</span></div></div>`:`<div class="magic-invitation"><span>Three decisions in the conversation.</span><strong>The project shouldn’t need a second round of typing.</strong></div>`}<div class="magic-actions">${reveal?`${state.meetingPlanApplied?'<span class="magic-saved">✓ Kept in your sample plan</span>':'<button class="primary" onclick="keepMeetingPlan()">Keep these two updates →</button>'}<button onclick="resetMeetingPlan()">${state.meetingPlanApplied?'Undo sample updates':'Back to the original'}</button>`:'<button class="primary" onclick="state.meetingPlanReveal=true;render()">✦ Show me what changed</button>'}</div><p class="sourceline">${reveal?'You choose what to keep. Each update links back to the meeting.':'Prepared in the background. A human reviews before the plan changes.'}</p></section></div><p class="tiny muted">Interactive concept · Fictional meeting and project data · No meeting joined or people notified.</p></div>`;};
function revealMeetingDecision(which){state.meetingPlanReveal=true;state.meetingPlanFocus=which;render()}
function keepMeetingPlan(){if(!state.meetingPlanApplied)state.beforeMeetingPlan={risk:state.risk,voice:state.voice};state.risk=true;state.voice=true;state.meetingPlanApplied=true;render();toast('Two updates kept in the sample plan. Nobody notified.')}
function resetMeetingPlan(){if(state.meetingPlanApplied){state.risk=state.beforeMeetingPlan?.risk??false;state.voice=state.beforeMeetingPlan?.voice??false}state.meetingPlanApplied=false;state.meetingPlanReveal=false;state.meetingPlanFocus=null;render()}
const pages={'meeting-plan':meetingPlan,morning,home,assistant,brief,plan,board,risk,meeting,room,voice,learning,developer,create};
function render(){let r=location.hash.slice(1)||'home';if(!pages[r])r='home';$('#main').innerHTML=pages[r]();document.querySelectorAll('[data-route]').forEach(el=>el.classList.toggle('active',el.dataset.route===r));document.querySelectorAll('#main .card > h2').forEach((h,i)=>{const icon=document.createElement('span');icon.className='panel-icon icon-'+(i%3);icon.textContent=['✦','◷','✓'][i%3];h.prepend(icon)});document.title=`Asana concept · ${r}`;window.scrollTo(0,0)}window.addEventListener('hashchange',render);render();
